void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    vec3 col = texture(iChannel1,uv).xyz;

    // Output to screen
    fragColor = vec4(col,1.0);
}

void mainImage( out vec4 O, in vec2 U )
{
    // initialization from https://www.shadertoy.com/view/tsjGRm
    vec2 R = iResolution.xy;
    vec2 uv = U/R.xy;
    U -= .5;
    if ( U == vec2(1,0) ) { O = vec4( iChannelResolution[0].xy, O.xy ); return; }
    vec4 V = T(vec2(1,0));
    if ( V.x == 0. && iChannelResolution[0].x > 0. )  { 
        vec3 col = texture(iChannel0, uv).xyz;
        O = vec4(col, 1.); 
    } else {
        vec4 v = texture(iChannel2, uv);
        vec4 p = texture(iChannel1, uv);
        vec4 pnew = p + v * 0.1;
        O = vec4(pnew.xyz, 1.);
    }
}

void mainImage( out vec4 O, in vec2 U )
{
    // initialization from https://www.shadertoy.com/view/tsjGRm
    vec2 R = iResolution.xy;
    vec2 uv = U/R.xy;
    U -= .5;
    if ( U == vec2(1,0) ) { O = vec4( iChannelResolution[0].xy, O.xy ); return; }
    vec4 V = T(vec2(1,0));
    if ( V.x == 0. && iChannelResolution[0].x > 0. )  { 
        O = vec4(vec3(0.), 1.); 
    } else {
        vec4 v = texture(iChannel2, uv);
        vec4 p = texture(iChannel1, uv);
        vec4 vnew = v - 0.1 * sin(p) * cos(p);
        O = vec4(vnew.xyz, 1.);
    }
}
